create type public.content_status as enum ('draft','published','archived');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null, role text not null default 'editor' check(role in ('admin','editor')), created_at timestamptz not null default now());
create table public.content_items (id uuid primary key default gen_random_uuid(), content_type text not null check(content_type in ('page','activity','darse','article','announcement','timeline')), slug text not null, status public.content_status not null default 'draft', featured_media_url text, event_date date, published_at timestamptz, created_by uuid references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(content_type,slug));
create table public.content_translations (id uuid primary key default gen_random_uuid(), content_id uuid not null references public.content_items(id) on delete cascade, locale text not null check(locale in ('en','ml','ar')), title text not null, summary text, body text, unique(content_id,locale));
create table public.albums (id uuid primary key default gen_random_uuid(), title text not null, slug text not null unique, description text, status public.content_status not null default 'draft', event_date date, created_at timestamptz not null default now());
create table public.media (id uuid primary key default gen_random_uuid(), album_id uuid references public.albums(id) on delete set null, storage_path text not null, alt_text jsonb not null default '{}'::jsonb, caption jsonb not null default '{}'::jsonb, sort_order integer not null default 0, created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.content_items enable row level security; alter table public.content_translations enable row level security; alter table public.albums enable row level security; alter table public.media enable row level security;
create policy "Public reads published content" on public.content_items for select using(status='published');
create policy "Public reads published translations" on public.content_translations for select using(exists(select 1 from public.content_items ci where ci.id=content_id and ci.status='published'));
create policy "Public reads published albums" on public.albums for select using(status='published');
create policy "Public reads media in published albums" on public.media for select using(exists(select 1 from public.albums a where a.id=album_id and a.status='published'));
-- Add authenticated editor/admin write policies only after establishing a trusted role assignment workflow. Never allow self-assigned roles.
